// go-lemon: Pure Go LALR(1) parser generator ported from SQLite's lemon.
//
// engine.go — LALR(1) parser engine runtime.
// This is the Go port of lempar.c from SQLite. It implements the
// shift/reduce parser engine that drives parse tables generated by
// the go-lemon generator (or the C lemon generator).
//
// The engine is generic: it operates on pre-generated parse tables
// and calls user-supplied action functions when reducing by a rule.

package main

import "fmt"

// ParserAction represents an action code from the parse tables.
// Encoding (matching lemon's convention):
//
//	  0 <= N <= YY_MAX_SHIFT          Shift N (goto state N)
//	  YY_MIN_SHIFTREDUCE <= N <= YY_MAX_SHIFTREDUCE  Shift+Reduce by rule N-YY_MIN_SHIFTREDUCE
//	  N == YY_ERROR_ACTION            Syntax error
//	  N == YY_ACCEPT_ACTION           Accept input
//	  N == YY_NO_ACTION               No action (unused slot)
//	  YY_MIN_REDUCE <= N <= YY_MAX_REDUCE  Reduce by rule N-YY_MIN_REDUCE
type ParserAction int32

// ParseTables holds all pre-generated parse tables for a grammar.
// These are generated by the go-lemon tool from a .y grammar file.
type ParseTables struct {
	// Action table: for state S and lookahead X, the action is:
	//   yy_action[yy_shift_ofst[S] + X]
	// or yy_default[S] as fallback.
	Action    []ParserAction
	Lookahead []int // yy_lookahead[i] must equal lookahead for yy_action[i] to be valid
	ShiftOfst []int // offset into yy_action for shifting terminals, indexed by state
	ReduceOfst []int // offset into yy_action for shifting non-terminals after reduce
	Default   []ParserAction // default action for each state
	Goto      []map[int]ParserAction // goto[state][nonTermCode] = nextState

	// Rule information
	RuleInfoLhs  []int // for each rule, the LHS symbol
	RuleInfoNRhs []int // for each rule, negative of RHS symbol count
	RuleName     []string // rule names for tracing
	TokenName    []string // token names for tracing

	// Sizes
	YYShiftCount    int // number of shift states
	YYReduceCount   int // number of reduce states
	YYActTabCount   int // size of action table
	YYNToken        int // number of terminal symbols
	YYNState        int // combined number of states
	YYNRule         int // number of rules
	YYMaxShift      ParserAction
	YYMinShiftReduce ParserAction
	YYMaxShiftReduce ParserAction
	YYMinReduce     ParserAction
	YYMaxReduce     ParserAction
	YYErrorAction   ParserAction
	YYAcceptAction  ParserAction
	YYNoAction      ParserAction
	YYNoCode        int // symbol code meaning "no lookahead"
	YYWildcard      int // wildcard token code, or -1 if none
	YYFallback      []int // fallback token map, or nil if none

	// Destructors: for each symbol, a destructor function (may be nil)
	Destructors []func(interface{})
}

// ParseState represents the parser's current state.
// Each entry on the parser stack has a state number, major token, and minor value.
type ParseState struct {
	StateNo ParserAction // state number or reduce action
	Major   int          // major token code
	Minor   interface{}  // minor (semantic) value
}

// Parser is an LALR(1) parser instance.
// It uses pre-generated tables and processes tokens via the Parse method.
type Parser struct {
	tables  *ParseTables
	stack   []ParseState
	pos     int // current stack position (top of stack index)
	trace   bool
	action  ActionFunc // user-supplied reduce action callback
	// Error recovery state
	errCount int
	ExtraCtx interface{} // extra context from %extra_argument
}

// NewParser creates a new parser instance with the given tables.
func NewParser(tables *ParseTables) *Parser {
	p := &Parser{
		tables: tables,
		stack:  make([]ParseState, 0, 100),
		pos:    -1,
	}
	// Initialize with state 0
	p.push(ParseState{StateNo: 0, Major: 0})
	return p
}

// SetTrace enables or disables tracing output.
func (p *Parser) SetTrace(on bool) {
	p.trace = on
}

func (p *Parser) push(s ParseState) {
	p.stack = append(p.stack, s)
	p.pos++
}

func (p *Parser) pop() ParseState {
	if p.pos < 0 {
		return ParseState{}
	}
	s := p.stack[p.pos]
	p.stack = p.stack[:p.pos]
	p.pos--
	return s
}

func (p *Parser) top() *ParseState {
	if p.pos < 0 {
		return nil
	}
	return &p.stack[p.pos]
}

// growStack ensures there's room for one more entry.
func (p *Parser) growStack() bool {
	// slice already grows dynamically in Go
	return false // no error
}

// safeTokenName returns the token name for a code, or "?" if unavailable.
func safeTokenName(t *ParseTables, code int) string {
	if t.TokenName != nil && code >= 0 && code < len(t.TokenName) {
		return t.TokenName[code]
	}
	return "?"
}

// yyFindShiftAction finds the action for a terminal lookahead token.
func (p *Parser) yyFindShiftAction(lookahead int, stateNo ParserAction) ParserAction {
	t := p.tables
	if stateNo > ParserAction(t.YYMaxShift) {
		return stateNo
	}

	i := t.ShiftOfst[stateNo]
	if i < 0 || i > t.YYActTabCount || i+lookahead >= len(t.Lookahead) {
		return t.Default[stateNo]
	}
	idx := i + lookahead
	if idx >= len(t.Lookahead) || t.Lookahead[idx] != lookahead {
		// Fallback
		if t.YYFallback != nil && lookahead < len(t.YYFallback) && t.YYFallback[lookahead] != 0 {
			fallback := t.YYFallback[lookahead]
			if p.trace {
					fmt.Printf("FALLBACK %s => %s\n", safeTokenName(t, lookahead), safeTokenName(t, fallback))
			}
			return p.yyFindShiftAction(fallback, stateNo)
		}
		// Wildcard
		if t.YYWildcard >= 0 && lookahead > 0 {
			j := idx - lookahead + t.YYWildcard
			if j < len(t.Lookahead) && t.Lookahead[j] == t.YYWildcard {
				if p.trace {
						fmt.Printf("WILDCARD %s => %s\n", safeTokenName(t, lookahead), safeTokenName(t, t.YYWildcard))
				}
				return t.Action[j]
			}
		}
		return t.Default[stateNo]
	}
	if idx < len(t.Action) {
		return t.Action[idx]
	}
	return t.Default[stateNo]
}

// yyFindReduceAction finds the action for a non-terminal lookahead (after reduce).
func (p *Parser) yyFindReduceAction(stateNo ParserAction, lookahead int) ParserAction {
	t := p.tables
	// Use the Goto table (map from nonTermCode to nextState)
	if t.Goto != nil && int(stateNo) < len(t.Goto) && t.Goto[stateNo] != nil {
		if act, ok := t.Goto[stateNo][lookahead]; ok {
			return act
		}
	}
	// Fallback: try the ReduceOfst table
	if int(stateNo) <= t.YYReduceCount {
		i := t.ReduceOfst[stateNo] + lookahead
		if i >= 0 && i < len(t.Lookahead) && i < len(t.Action) && t.Lookahead[i] == lookahead {
			return t.Action[i]
		}
	}
	// Default: return 0 (will cause error)
	return 0
}

// yy_destructor calls the destructor for a symbol value.
func (p *Parser) yyDestructor(major int, minor interface{}) {
	if p.tables.Destructors != nil && major < len(p.tables.Destructors) && p.tables.Destructors[major] != nil {
		p.tables.Destructors[major](minor)
	}
}

// yyPopParserStack pops one element from the stack, calling its destructor.
func (p *Parser) yyPopParserStack() {
	if p.pos < 0 {
		return
	}
	top := &p.stack[p.pos]
	if p.trace {
		traceName := "?"
		if p.tables.TokenName != nil && top.Major < len(p.tables.TokenName) {
			traceName = p.tables.TokenName[top.Major]
		}
		fmt.Printf("Popping %s\n", traceName)
	}
	p.yyDestructor(top.Major, top.Minor)
	p.pop()
}

// yyStackOverflow handles parser stack overflow.
func (p *Parser) yyStackOverflow() {
	if p.trace {
		fmt.Printf("Stack Overflow!\n")
	}
	for p.pos >= 0 {
		p.yyPopParserStack()
	}
}

// yyShift performs a shift action.
func (p *Parser) yyShift(newState ParserAction, major int, minor interface{}) {
	t := p.tables
	if newState > t.YYMaxShift {
		newState += t.YYMinReduce - t.YYMinShiftReduce
	}
	p.push(ParseState{
		StateNo: newState,
		Major:   major,
		Minor:   minor,
	})
	if p.trace {
		traceName := "?"
		if t.TokenName != nil && major < len(t.TokenName) {
			traceName = t.TokenName[major]
		}
		if int(newState) < t.YYNState {
			fmt.Printf("Shift '%s', go to state %d\n", traceName, newState)
		} else {
			fmt.Printf("Shift '%s', pending reduce %d\n", traceName, newState-t.YYMinReduce)
		}
	}
}

// ActionFunc is the type for user-supplied reduce action functions.
// The function receives the rule number, the parser's semantic stack,
// and the lookahead information. It should modify the stack as needed.
type ActionFunc func(ruleNo int, parser *Parser, lookahead int, lookaheadToken interface{})

// yyReduce performs a reduce action and the shift that follows.
func (p *Parser) yyReduce(ruleNo int, lookahead int, lookaheadToken interface{}) ParserAction {
	t := p.tables
	top := p.pos

	if p.trace && ruleNo < len(t.RuleName) {
		nrhs := -t.RuleInfoNRhs[ruleNo]
		if nrhs > 0 && top+nrhs < len(p.stack) {
			fmt.Printf("Reduce %d [%s], pop back to state %d.\n",
				ruleNo, t.RuleName[ruleNo], p.stack[top-nrhs].StateNo)
		} else {
			fmt.Printf("Reduce %d [%s].\n", ruleNo, t.RuleName[ruleNo])
		}
	}

	// Get goto information
	if ruleNo >= len(t.RuleInfoLhs) {
		return t.YYErrorAction
	}
	gotoSym := t.RuleInfoLhs[ruleNo]
	nrhs := t.RuleInfoNRhs[ruleNo] // negative of RHS count
	size := -nrhs

	// LHS slot: the position on the stack that will become the LHS after reducing.
	// In lemon convention, for a rule "A ::= B C D." (N=3 RHS symbols):
	//   stack[top-2] = B = $1 position = LHS slot ($$)
	//   stack[top-1] = C = $2 position
	//   stack[top]   = D = $3 position
	// The action code writes $$ to stack[top-(N-1)] = stack[top-2].
	// After popping N RHS symbols, the LHS lives at the new top.
	lhsSlot := top - size + 1 // = top - N + 1 = first RHS position

	// For empty rules (nrhs == 0), ensure the stack has room for the LHS
	// and set p.pos so that $$ (= p.stack[pos].Minor) targets the LHS slot.
	if nrhs == 0 {
		p.stack = append(p.stack, ParseState{})
		p.pos = lhsSlot
	}

	// Call the user action — this may set p.stack[lhsSlot].Minor via $$ assignment
	if p.action != nil {
		p.action(ruleNo, p, lookahead, lookaheadToken)
	}

	// Read the LHS value set by the action (from the $$ slot)
	lhsValue := p.stack[lhsSlot].Minor

	// Find the state after popping RHS and shifting LHS
	// nrhs is negative (e.g., -3 for 3 RHS), so top+nrhs goes backwards to the state before the first RHS
	stateNo := p.stack[top+nrhs].StateNo
	act := p.yyFindReduceAction(stateNo, gotoSym)

	// Pop RHS symbols and set LHS in place (like C lemon: reuse the first RHS slot)
	// Set the LHS values in the existing stack slot
	p.stack[lhsSlot] = ParseState{
		StateNo: act,
		Major:   gotoSym,
		Minor:   lhsValue,
	}
	p.pos = lhsSlot
	// Truncate stack to remove old entries beyond the new position.
	p.stack = p.stack[:lhsSlot+1]

	if p.trace {
		fmt.Printf("... then shift, go to state %d\n", act)
	}
	return act
}

// OnReduce sets the callback for reduce actions.
func (p *Parser) OnReduce(fn ActionFunc) {
	p.action = fn
}

// ParseResult describes the outcome of parsing.
type ParseResult int

const (
	ParseAccept  ParseResult = iota // Input accepted
	ParseError                      // Syntax error
	ParseStackOverflow              // Stack overflow
)

// Parse processes one token through the parser.
// yymajor is the token code (0 = EOF).
// yyminor is the token's semantic value.
// Returns ParseAccept on success (all input consumed),
// ParseError on syntax error, or ParseStackOverflow.
func (p *Parser) Parse(yymajor int, yyminor interface{}) ParseResult {
	t := p.tables
	if p.pos < 0 {
		return ParseError
	}

	yyact := p.stack[p.pos].StateNo

	if p.trace {
		traceName := "?"
		if t.TokenName != nil && yymajor < len(t.TokenName) {
			traceName = t.TokenName[yymajor]
		}
		if yyact < t.YYMinReduce {
			fmt.Printf("Input '%s' in state %d\n", traceName, yyact)
		} else {
			fmt.Printf("Input '%s' with pending reduce %d\n",
				traceName, yyact-t.YYMinReduce)
		}
	}

	for {
		if p.pos < 0 || p.pos >= len(p.stack) {
			return ParseError
		}
		yyact = p.yyFindShiftAction(yymajor, p.stack[p.pos].StateNo)

		// Check special actions first (Accept/Error/NoAction)
		if yyact == t.YYAcceptAction {
			p.pos = -1
			if p.trace {
				fmt.Printf("Accept!\n")
			}
			return ParseAccept
		}
		if yyact == t.YYErrorAction || yyact == t.YYNoAction {
			if p.trace {
				fmt.Printf("Syntax Error!\n")
			}
			return ParseError
		}

		// Reduce or shift
		if yyact >= t.YYMinReduce {
			ruleNo := int(yyact - t.YYMinReduce)
			if ruleNo >= t.YYNRule {
				return ParseError
			}
			yyact = p.yyReduce(ruleNo, yymajor, yyminor)
			continue
		} else {
			// Shift or shift+reduce
			p.yyShift(yyact, yymajor, yyminor)
			return ParseAccept
		}
	}
}

// Finalize clears all parser state, calling destructors for remaining stack elements.
func (p *Parser) Finalize() {
	for p.pos >= 0 {
		top := &p.stack[p.pos]
		if p.tables.TokenName != nil && top.Major < len(p.tables.TokenName) {
			// Call destructor if needed
		}
		p.yyDestructor(top.Major, top.Minor)
		p.pop()
	}
}
